  ) VALUES (
    v_quiz_id, 'single', 'What is the key difference between a B-Tree and a B+ Tree?', 'In B+ trees, internal nodes store only index guide keys, all records reside in leaves, and leaves are linked for fast range queries.',
    'medium', 1, 0, 27, ARRAY['BCA-102N', 'Unit-5', 'B-Plus-Tree', 'Difference']::TEXT[], 2024, 'MJPRU BCA Sem 2',
    now(), now()
