  INSERT INTO public.quiz_questions (
    quiz_id, type, prompt, explanation, difficulty, points, negative_marks,
    order_index, tags, year, exam_name, created_at, updated_at
  ) VALUES (
    v_quiz_id, 'single', 'If a system uses EVEN PARITY, what parity bit is appended to the 7-bit data word 1010110?', 'The data word has four 1s (already even). To keep total 1s even, the parity bit is 0... wait: 1+0+1+0+1+1+0 = four 1s. To keep it even, parity bit is 0. If it had three 1s, it would be 1.',
    'medium', 1, 0, 28, ARRAY['BCA-108N', 'Unit-2', 'Even-Parity']::TEXT[], 2024, 'MJPRU BCA Sem 2',
    now(), now()
  ) RETURNING id INTO v_q_id;

  INSERT INTO public.quiz_options (question_id, text, is_correct, order_index, created_at, updated_at) VALUES
