    (v_q_id, 'Either 1 or 0', false, 3, now(), now()),
    (v_q_id, 'Cannot be determined', false, 4, now(), now());

  INSERT INTO public.quiz_questions (
    quiz_id, type, prompt, explanation, difficulty, points, negative_marks,
    order_index, tags, year, exam_name, created_at, updated_at
  ) VALUES (
    v_quiz_id, 'single', 'Can a single parity bit detect two simultaneous bit errors in a word?', 'Simple parity can only detect odd numbers of bit flips; it fails when an even number of bits error.',
    'medium', 1, 0, 29, ARRAY['BCA-108N', 'Unit-2', 'Parity-Limitation']::TEXT[], 2024, 'MJPRU BCA Sem 2',
    now(), now()
  ) RETURNING id INTO v_q_id;

  INSERT INTO public.quiz_options (question_id, text, is_correct, order_index, created_at, updated_at) VALUES
