  ) VALUES (
    v_quiz_id, 'single', 'What is De Morgan''s First Law for set complements?', 'The complement of a union is the intersection of the complements: (A ∪ B)'' = A'' ∩ B''.',
    'easy', 1, 0, 13, ARRAY['BCA-401E', 'Unit-1', 'De-Morgan', 'Sets']::TEXT[], 2024, 'MJPRU BCA Sem 2',
    now(), now()
