    order_index, tags, year, exam_name, created_at, updated_at
  ) VALUES (
    v_quiz_id, 'single', 'What is the Cardinality Principle (Inclusion-Exclusion Principle) for two finite sets A and B?', 'To avoid double-counting elements in the intersection: |A ∪ B| = |A| + |B| - |A ∩ B|.',
    'easy', 1, 0, 15, ARRAY['BCA-401E', 'Unit-1', 'Inclusion-Exclusion', 'Formula']::TEXT[], 2024, 'MJPRU BCA Sem 2',
    now(), now()
  ) RETURNING id INTO v_q_id;

  INSERT INTO public.quiz_options (question_id, text, is_correct, order_index, created_at, updated_at) VALUES
