  INSERT INTO public.quiz_questions (
    quiz_id, type, prompt, explanation, difficulty, points, negative_marks,
    order_index, tags, year, exam_name, created_at, updated_at
  ) VALUES (
    v_quiz_id, 'single', 'What is the value of lim_{(x,y)->(0,0)} (xy) / (x^2 + y^2)?', 'Setting y = mx gives (m*x^2) / (x^2 + m^2*x^2) = m / (1 + m^2). Since this depends on m, the limit does not exist.',
    'medium', 1, 0, 3, ARRAY['BCA-401E', 'Unit-3', 'Multivariable-Limit', 'Non-Existence']::TEXT[], 2024, 'MJPRU BCA Sem 2',
    now(), now()
  ) RETURNING id INTO v_q_id;

  INSERT INTO public.quiz_options (question_id, text, is_correct, order_index, created_at, updated_at) VALUES
    (v_q_id, 'Limit does not exist because approaching along y = mx yields m / (1 + m^2), which depends on slope m', true, 1, now(), now()),
    (v_q_id, '0', false, 2, now(), now()),
    (v_q_id, '1', false, 3, now(), now()),
    (v_q_id, '1/2', false, 4, now(), now());

  INSERT INTO public.quiz_questions (
    quiz_id, type, prompt, explanation, difficulty, points, negative_marks,
