  ) VALUES (
    v_quiz_id, 'single', 'Evaluate lim_{(x,y)->(0,0)} (x^2 * y) / (x^4 + y^2):', 'Along parabolic paths y = mx^2, the ratio becomes m/(1+m^2), proving path dependence and non-existence.',
    'hard', 1, 0, 4, ARRAY['BCA-401E', 'Unit-3', 'Multivariable-Limit', 'Parabolic-Path']::TEXT[], 2024, 'MJPRU BCA Sem 2',
    now(), now()
  ) RETURNING id INTO v_q_id;

  INSERT INTO public.quiz_options (question_id, text, is_correct, order_index, created_at, updated_at) VALUES
    (v_q_id, 'Does not exist (along y = mx^2 it gives m / (1 + m^2), while along y = mx it gives 0)', true, 1, now(), now()),
    (v_q_id, '0', false, 2, now(), now()),
