  ) VALUES (
    v_quiz_id, 'single', 'If z = x^3 + y^3 - 3axy, what is ∂z/∂x?', 'Differentiating x^3 + y^3 - 3axy with respect to x (holding y constant): d(x^3)/dx = 3x^2, d(y^3)/dx = 0, d(-3axy)/dx = -3ay.',
    'easy', 1, 0, 7, ARRAY['BCA-401E', 'Unit-3', 'Partial-Derivative', 'Calculation']::TEXT[], 2024, 'MJPRU BCA Sem 2',
    now(), now()
  ) RETURNING id INTO v_q_id;

