  INSERT INTO public.quiz_questions (
    quiz_id, type, prompt, explanation, difficulty, points, negative_marks,
    order_index, tags, year, exam_name, created_at, updated_at
  ) VALUES (
    v_quiz_id, 'single', 'A function f(x, y) is called a Homogeneous Function of degree n if for any scalar t > 0:', 'By definition, scaling all independent variables by t scales the entire function by t^n.',
    'easy', 1, 0, 11, ARRAY['BCA-401E', 'Unit-3', 'Homogeneous-Function', 'Definition']::TEXT[], 2024, 'MJPRU BCA Sem 2',
    now(), now()
  ) RETURNING id INTO v_q_id;

  INSERT INTO public.quiz_options (question_id, text, is_correct, order_index, created_at, updated_at) VALUES
    (v_q_id, 'f(tx, ty) = t^n * f(x, y)', true, 1, now(), now()),
