  INSERT INTO public.quiz_questions (
    quiz_id, type, prompt, explanation, difficulty, points, negative_marks,
    order_index, tags, year, exam_name, created_at, updated_at
  ) VALUES (
    v_quiz_id, 'single', 'What is the degree of homogeneity n of the function f(x, y) = (x^3 + y^3) / (x + y)?', 'f(tx, ty) = (t^3 x^3 + t^3 y^3) / (tx + ty) = t^2 (x^3 + y^3) / (x + y) = t^2 f(x, y). Degree n = 3 - 1 = 2.',
    'easy', 1, 0, 12, ARRAY['BCA-401E', 'Unit-3', 'Homogeneous-Degree', 'Calculation']::TEXT[], 2024, 'MJPRU BCA Sem 2',
    now(), now()
  ) RETURNING id INTO v_q_id;

  INSERT INTO public.quiz_options (question_id, text, is_correct, order_index, created_at, updated_at) VALUES
    (v_q_id, '2', true, 1, now(), now()),
    (v_q_id, '3', false, 2, now(), now()),
    (v_q_id, '1', false, 3, now(), now()),
    (v_q_id, '0', false, 4, now(), now());

  INSERT INTO public.quiz_questions (
    quiz_id, type, prompt, explanation, difficulty, points, negative_marks,
    order_index, tags, year, exam_name, created_at, updated_at
  ) VALUES (
    v_quiz_id, 'single', 'What is the statement of Euler''s Theorem for a homogeneous function u = f(x, y) of degree n?', 'Euler''s theorem states: for any homogeneous function u of degree n, x(∂u/∂x) + y(∂u/∂y) = nu.',
    'easy', 1, 0, 13, ARRAY['BCA-401E', 'Unit-3', 'Euler-Theorem', 'Statement']::TEXT[], 2024, 'MJPRU BCA Sem 2',
    now(), now()
  ) RETURNING id INTO v_q_id;

  INSERT INTO public.quiz_options (question_id, text, is_correct, order_index, created_at, updated_at) VALUES
    (v_q_id, 'x * (∂u/∂x) + y * (∂u/∂y) = n * u', true, 1, now(), now()),
    (v_q_id, 'x * (∂u/∂x) - y * (∂u/∂y) = 0', false, 2, now(), now()),
    (v_q_id, '∂u/∂x + ∂u/∂y = n * u', false, 3, now(), now()),
    (v_q_id, 'x^2 (∂u/∂x) + y^2 (∂u/∂y) = n(n-1)u', false, 4, now(), now());

  INSERT INTO public.quiz_questions (
    quiz_id, type, prompt, explanation, difficulty, points, negative_marks,
    order_index, tags, year, exam_name, created_at, updated_at
  ) VALUES (
    v_quiz_id, 'single', 'What is the second-order extension of Euler''s Theorem for a homogeneous function u of degree n?', 'The second-order Euler identity is x^2 u_xx + 2xy u_xy + y^2 u_yy = n(n - 1)u.',
    'medium', 1, 0, 14, ARRAY['BCA-401E', 'Unit-3', 'Euler-Theorem', 'Second-Order']::TEXT[], 2024, 'MJPRU BCA Sem 2',
    now(), now()
  ) RETURNING id INTO v_q_id;

  INSERT INTO public.quiz_options (question_id, text, is_correct, order_index, created_at, updated_at) VALUES
    (v_q_id, 'x^2 (∂^2u/∂x^2) + 2xy (∂^2u/∂x∂y) + y^2 (∂^2u/∂y^2) = n(n - 1)u', true, 1, now(), now()),
    (v_q_id, 'x^2 (∂^2u/∂x^2) + y^2 (∂^2u/∂y^2) = n^2 u', false, 2, now(), now()),
    (v_q_id, 'x^2 u_xx + 2xy u_xy + y^2 u_yy = n u', false, 3, now(), now()),
    (v_q_id, 'u_xx + u_yy = 0', false, 4, now(), now());

  INSERT INTO public.quiz_questions (
    quiz_id, type, prompt, explanation, difficulty, points, negative_marks,
    order_index, tags, year, exam_name, created_at, updated_at
  ) VALUES (
    v_quiz_id, 'single', 'If u = sin^(-1)[(x + y) / (sqrt(x) + sqrt(y))], what is x(∂u/∂x) + y(∂u/∂y)?', 'Let z = sin(u) = (x+y)/(sqrt(x)+sqrt(y)), which is homogeneous of degree 1 - 1/2 = 1/2. By Euler: x(∂z/∂x) + y(∂z/∂y) = (1/2)z => cos(u)[x(∂u/∂x) + y(∂u/∂y)] = (1/2)sin(u) => x(∂u/∂x) + y(∂u/∂y) = (1/2)tan(u).',
    'hard', 1, 0, 15, ARRAY['BCA-401E', 'Unit-3', 'Euler-Theorem', 'Trigonometric']::TEXT[], 2024, 'MJPRU BCA Sem 2',
    now(), now()
  ) RETURNING id INTO v_q_id;

  INSERT INTO public.quiz_options (question_id, text, is_correct, order_index, created_at, updated_at) VALUES
    (v_q_id, '(1/2) tan(u)', true, 1, now(), now()),
    (v_q_id, '(1/2) sin(u)', false, 2, now(), now()),
    (v_q_id, 'tan(u)', false, 3, now(), now()),
    (v_q_id, '2 tan(u)', false, 4, now(), now());

  INSERT INTO public.quiz_questions (
    quiz_id, type, prompt, explanation, difficulty, points, negative_marks,
    order_index, tags, year, exam_name, created_at, updated_at
  ) VALUES (
    v_quiz_id, 'single', 'If u = log[(x^4 + y^4) / (x + y)], find x(∂u/∂x) + y(∂u/∂y):', 'Let z = e^u = (x^4 + y^4)/(x + y), degree n = 4 - 1 = 3. x(∂z/∂x) + y(∂z/∂y) = 3z => e^u [x(∂u/∂x) + y(∂u/∂y)] = 3 e^u => x(∂u/∂x) + y(∂u/∂y) = 3.',
    'medium', 1, 0, 16, ARRAY['BCA-401E', 'Unit-3', 'Euler-Theorem', 'Logarithmic']::TEXT[], 2024, 'MJPRU BCA Sem 2',
    now(), now()
  ) RETURNING id INTO v_q_id;

  INSERT INTO public.quiz_options (question_id, text, is_correct, order_index, created_at, updated_at) VALUES
    (v_q_id, '3', true, 1, now(), now()),
    (v_q_id, '3u', false, 2, now(), now()),
    (v_q_id, 'e^(3u)', false, 3, now(), now()),
    (v_q_id, '1/3', false, 4, now(), now());

  INSERT INTO public.quiz_questions (
    quiz_id, type, prompt, explanation, difficulty, points, negative_marks,
    order_index, tags, year, exam_name, created_at, updated_at
  ) VALUES (
    v_quiz_id, 'single', 'What is the Total Differential dz of a function z = f(x, y)?', 'The total differential dz is the linear approximation given by (∂z/∂x)dx + (∂z/∂y)dy.',
    'easy', 1, 0, 17, ARRAY['BCA-401E', 'Unit-3', 'Total-Differential', 'Formula']::TEXT[], 2024, 'MJPRU BCA Sem 2',
    now(), now()
  ) RETURNING id INTO v_q_id;

  INSERT INTO public.quiz_options (question_id, text, is_correct, order_index, created_at, updated_at) VALUES
    (v_q_id, 'dz = (∂z/∂x) dx + (∂z/∂y) dy', true, 1, now(), now()),
    (v_q_id, 'dz = (∂z/∂x) + (∂z/∂y)', false, 2, now(), now()),
    (v_q_id, 'dz = dx dy', false, 3, now(), now()),
    (v_q_id, 'dz = (∂^2z/∂x∂y) dx dy', false, 4, now(), now());

  INSERT INTO public.quiz_questions (
    quiz_id, type, prompt, explanation, difficulty, points, negative_marks,
    order_index, tags, year, exam_name, created_at, updated_at
  ) VALUES (
    v_quiz_id, 'single', 'If z = f(x, y), where x = g(t) and y = h(t), what is the Chain Rule for dz/dt?', 'By the multivariable chain rule, dz/dt = (∂z/∂x)(dx/dt) + (∂z/∂y)(dy/dt).',
    'easy', 1, 0, 18, ARRAY['BCA-401E', 'Unit-3', 'Chain-Rule', 'Single-Parameter']::TEXT[], 2024, 'MJPRU BCA Sem 2',
    now(), now()
  ) RETURNING id INTO v_q_id;

  INSERT INTO public.quiz_options (question_id, text, is_correct, order_index, created_at, updated_at) VALUES
    (v_q_id, 'dz/dt = (∂z/∂x)(dx/dt) + (∂z/∂y)(dy/dt)', true, 1, now(), now()),
    (v_q_id, 'dz/dt = (∂z/∂x) + (∂z/∂y)', false, 2, now(), now()),
    (v_q_id, 'dz/dt = (dx/dt)(dy/dt)', false, 3, now(), now()),
    (v_q_id, 'dz/dt = (∂z/∂x)(dy/dt) + (∂z/∂y)(dx/dt)', false, 4, now(), now());

  INSERT INTO public.quiz_questions (
    quiz_id, type, prompt, explanation, difficulty, points, negative_marks,
    order_index, tags, year, exam_name, created_at, updated_at
  ) VALUES (
    v_quiz_id, 'single', 'If z = f(x, y) where x = u + v and y = u - v, what is ∂z/∂u?', '∂z/∂u = (∂z/∂x)(∂x/∂u) + (∂z/∂y)(∂y/∂u) = (∂z/∂x)(1) + (∂z/∂y)(1) = ∂z/∂x + ∂z/∂y.',
    'easy', 1, 0, 19, ARRAY['BCA-401E', 'Unit-3', 'Chain-Rule', 'Two-Parameters']::TEXT[], 2024, 'MJPRU BCA Sem 2',
    now(), now()
  ) RETURNING id INTO v_q_id;

  INSERT INTO public.quiz_options (question_id, text, is_correct, order_index, created_at, updated_at) VALUES
    (v_q_id, '∂z/∂x + ∂z/∂y', true, 1, now(), now()),
    (v_q_id, '∂z/∂x - ∂z/∂y', false, 2, now(), now()),
    (v_q_id, '(∂z/∂x)(∂z/∂y)', false, 3, now(), now()),
    (v_q_id, '0', false, 4, now(), now());

  INSERT INTO public.quiz_questions (
    quiz_id, type, prompt, explanation, difficulty, points, negative_marks,
    order_index, tags, year, exam_name, created_at, updated_at
  ) VALUES (
    v_quiz_id, 'single', 'If z = f(x, y) where x = u + v and y = u - v, what is ∂z/∂v?', '∂z/∂v = (∂z/∂x)(∂x/∂v) + (∂z/∂y)(∂y/∂v) = (∂z/∂x)(1) + (∂z/∂y)(-1) = ∂z/∂x - ∂z/∂y.',
    'easy', 1, 0, 20, ARRAY['BCA-401E', 'Unit-3', 'Chain-Rule', 'Two-Parameters']::TEXT[], 2024, 'MJPRU BCA Sem 2',
    now(), now()
  ) RETURNING id INTO v_q_id;

  INSERT INTO public.quiz_options (question_id, text, is_correct, order_index, created_at, updated_at) VALUES
    (v_q_id, '∂z/∂x - ∂z/∂y', true, 1, now(), now()),
