  INSERT INTO public.quiz_questions (
    quiz_id, type, prompt, explanation, difficulty, points, negative_marks,
    order_index, tags, year, exam_name, created_at, updated_at
  ) VALUES (
    v_quiz_id, 'single', 'What is the Jacobian of u and v with respect to x and y, denoted J = ∂(u, v) / ∂(x, y)?', 'The Jacobian determinant is defined as det([[u_x, u_y], [v_x, v_y]]) = (∂u/∂x)(∂v/∂y) - (∂u/∂y)(∂v/∂x).',
    'easy', 1, 0, 21, ARRAY['BCA-401E', 'Unit-3', 'Jacobian', 'Definition']::TEXT[], 2024, 'MJPRU BCA Sem 2',
    now(), now()
  ) RETURNING id INTO v_q_id;

  INSERT INTO public.quiz_options (question_id, text, is_correct, order_index, created_at, updated_at) VALUES
    (v_q_id, 'The determinant of the matrix [[∂u/∂x, ∂u/∂y], [∂v/∂x, ∂v/∂y]]', true, 1, now(), now()),
    (v_q_id, 'The sum (∂u/∂x) + (∂v/∂y)', false, 2, now(), now()),
    (v_q_id, 'The product (∂u/∂x)(∂v/∂y)', false, 3, now(), now()),
    (v_q_id, 'A vector cross product', false, 4, now(), now());

  INSERT INTO public.quiz_questions (
    quiz_id, type, prompt, explanation, difficulty, points, negative_marks,
    order_index, tags, year, exam_name, created_at, updated_at
  ) VALUES (
    v_quiz_id, 'single', 'What is the Inverse Property of Jacobians: if J = ∂(u, v)/∂(x, y) and J'' = ∂(x, y)/∂(u, v)?', 'Similar to single variable dy/dx * dx/dy = 1, for Jacobians J * J'' = 1 (provided J != 0).',
    'easy', 1, 0, 22, ARRAY['BCA-401E', 'Unit-3', 'Jacobian', 'Inverse-Property']::TEXT[], 2024, 'MJPRU BCA Sem 2',
    now(), now()
  ) RETURNING id INTO v_q_id;

  INSERT INTO public.quiz_options (question_id, text, is_correct, order_index, created_at, updated_at) VALUES
    (v_q_id, 'J * J'' = 1', true, 1, now(), now()),
    (v_q_id, 'J + J'' = 0', false, 2, now(), now()),
    (v_q_id, 'J * J'' = -1', false, 3, now(), now()),
