  ) VALUES (
    v_quiz_id, 'single', 'What is the Jacobian ∂(x, y)/∂(r, θ) for Cartesian coordinates in terms of polar coordinates (x = r cos θ, y = r sin θ)?', 'det([[cos θ, -r sin θ], [sin θ, r cos θ]]) = r cos^2 θ + r sin^2 θ = r.',
