  INSERT INTO public.quiz_questions (
    quiz_id, type, prompt, explanation, difficulty, points, negative_marks,
    order_index, tags, year, exam_name, created_at, updated_at
  ) VALUES (
    v_quiz_id, 'single', 'At a Stationary (Critical) Point (a, b) of a function f(x, y), what must hold?', 'The necessary condition for an interior extremum is that both first partial derivatives vanish: ∂f/∂x = 0 and ∂f/∂y = 0.',
    'easy', 1, 0, 27, ARRAY['BCA-401E', 'Unit-3', 'Maxima-Minima', 'Critical-Points']::TEXT[], 2024, 'MJPRU BCA Sem 2',
    now(), now()
  ) RETURNING id INTO v_q_id;

  INSERT INTO public.quiz_options (question_id, text, is_correct, order_index, created_at, updated_at) VALUES
    (v_q_id, 'f_x(a, b) = 0 and f_y(a, b) = 0 simultaneously', true, 1, now(), now()),
    (v_q_id, 'f(a, b) = 0', false, 2, now(), now()),
    (v_q_id, 'f_xx(a, b) = 0', false, 3, now(), now()),
    (v_q_id, 'f_x(a, b) > 0', false, 4, now(), now());

  INSERT INTO public.quiz_questions (
    quiz_id, type, prompt, explanation, difficulty, points, negative_marks,
    order_index, tags, year, exam_name, created_at, updated_at
  ) VALUES (
    v_quiz_id, 'single', 'Let r = ∂^2f/∂x^2, s = ∂^2f/∂x∂y, and t = ∂^2f/∂y^2 at a critical point (a, b). What does rt - s^2 > 0 and r < 0 indicate?', 'When the discriminant rt - s^2 > 0 and r < 0 (concave down), f has a local maximum at (a, b).',
    'medium', 1, 0, 28, ARRAY['BCA-401E', 'Unit-3', 'Maxima-Minima', 'Second-Derivative-Test']::TEXT[], 2024, 'MJPRU BCA Sem 2',
    now(), now()
  ) RETURNING id INTO v_q_id;

  INSERT INTO public.quiz_options (question_id, text, is_correct, order_index, created_at, updated_at) VALUES
    (v_q_id, 'f(a, b) is a local MAXIMUM', true, 1, now(), now()),
    (v_q_id, 'f(a, b) is a local minimum', false, 2, now(), now()),
    (v_q_id, 'A saddle point', false, 3, now(), now()),
    (v_q_id, 'Inconclusive test', false, 4, now(), now());

