  ) VALUES (
    v_quiz_id, 'single', 'Let r = f_xx, s = f_xy, and t = f_yy at a critical point. What does rt - s^2 > 0 and r > 0 indicate?', 'When rt - s^2 > 0 and r > 0 (concave up), f has a local minimum at (a, b).',
    'medium', 1, 0, 29, ARRAY['BCA-401E', 'Unit-3', 'Maxima-Minima', 'Local-Minimum']::TEXT[], 2024, 'MJPRU BCA Sem 2',
    now(), now()
  ) RETURNING id INTO v_q_id;

  INSERT INTO public.quiz_options (question_id, text, is_correct, order_index, created_at, updated_at) VALUES
