  ) VALUES (
    v_quiz_id, 'single', 'In the method of Lagrange Multipliers, what vector condition must hold at the constrained extremum?', 'At a constrained extremum, the contour curve of f is tangent to the constraint curve g = 0, so their gradient vectors are parallel: ∇f = λ∇g.',
    'medium', 1, 0, 35, ARRAY['BCA-401E', 'Unit-3', 'Lagrange-Multipliers', 'Condition']::TEXT[], 2024, 'MJPRU BCA Sem 2',
    now(), now()
  ) RETURNING id INTO v_q_id;

  INSERT INTO public.quiz_options (question_id, text, is_correct, order_index, created_at, updated_at) VALUES
