    order_index, tags, year, exam_name, created_at, updated_at
  ) VALUES (
    v_quiz_id, 'single', 'What is the Limit Comparison Test for positive term series Σ u_n and Σ v_n?', 'If the limit of the ratio is a non-zero finite number L, both series share the exact same convergence behavior.',
    'easy', 1, 0, 15, ARRAY['BCA-401E', 'Unit-4', 'Limit-Comparison-Test', 'Statement']::TEXT[], 2024, 'MJPRU BCA Sem 2',
    now(), now()
  ) RETURNING id INTO v_q_id;

  INSERT INTO public.quiz_options (question_id, text, is_correct, order_index, created_at, updated_at) VALUES
    (v_q_id, 'If lim_{n->infinity} (u_n / v_n) = L (where 0 < L < infinity), then both series either converge together or diverge together', true, 1, now(), now()),
    (v_q_id, 'If L = 0, both diverge', false, 2, now(), now()),
