    order_index, tags, year, exam_name, created_at, updated_at
  ) VALUES (
    v_quiz_id, 'single', 'Determine the convergence of Σ 1 / (n^2 + 5):', '1/(n^2 + 5) < 1/n^2. Since Σ 1/n^2 converges, Σ 1/(n^2 + 5) converges by comparison.',
    'easy', 1, 0, 16, ARRAY['BCA-401E', 'Unit-4', 'Comparison-Test', 'Application']::TEXT[], 2024, 'MJPRU BCA Sem 2',
    now(), now()
  ) RETURNING id INTO v_q_id;

  INSERT INTO public.quiz_options (question_id, text, is_correct, order_index, created_at, updated_at) VALUES
    (v_q_id, 'Convergent (by comparison with convergent p-series Σ 1/n^2, p = 2 > 1)', true, 1, now(), now()),
