    (v_q_id, 'Oscillatory', false, 3, now(), now()),
    (v_q_id, 'Unbounded', false, 4, now(), now());

  INSERT INTO public.quiz_questions (
    quiz_id, type, prompt, explanation, difficulty, points, negative_marks,
    order_index, tags, year, exam_name, created_at, updated_at
  ) VALUES (
    v_quiz_id, 'single', 'Determine the convergence of Σ (n + 1) / (n^3 - 2):', 'u_n / v_n = [(n+1)/(n^3-2)] / [1/n^2] = (n^3+n^2)/(n^3-2) -> 1 as n -> inf. Since Σ 1/n^2 converges, Σ u_n converges.',
    'medium', 1, 0, 17, ARRAY['BCA-401E', 'Unit-4', 'Limit-Comparison', 'Application']::TEXT[], 2024, 'MJPRU BCA Sem 2',
    now(), now()
  ) RETURNING id INTO v_q_id;

  INSERT INTO public.quiz_options (question_id, text, is_correct, order_index, created_at, updated_at) VALUES
    (v_q_id, 'Convergent (by Limit Comparison with v_n = 1/n^2, p = 2 > 1)', true, 1, now(), now()),
    (v_q_id, 'Divergent', false, 2, now(), now()),
    (v_q_id, 'Oscillatory', false, 3, now(), now()),
    (v_q_id, 'Inconclusive', false, 4, now(), now());

  INSERT INTO public.quiz_questions (
    quiz_id, type, prompt, explanation, difficulty, points, negative_marks,
    order_index, tags, year, exam_name, created_at, updated_at
  ) VALUES (
    v_quiz_id, 'single', 'What is D''Alembert''s Ratio Test for a positive term series Σ u_n with lim_{n->infinity} (u_(n+1) / u_n) = L?', 'D''Alembert''s ratio test: L < 1 => converges; L > 1 => diverges; L = 1 => test is inconclusive.',
    'easy', 1, 0, 18, ARRAY['BCA-401E', 'Unit-4', 'Ratio-Test', 'Statement']::TEXT[], 2024, 'MJPRU BCA Sem 2',
    now(), now()
  ) RETURNING id INTO v_q_id;

  INSERT INTO public.quiz_options (question_id, text, is_correct, order_index, created_at, updated_at) VALUES
    (v_q_id, 'Converges if L < 1, diverges if L > 1, and test fails (inconclusive) if L = 1', true, 1, now(), now()),
    (v_q_id, 'Converges if L > 1, diverges if L < 1', false, 2, now(), now()),
    (v_q_id, 'Converges if L = 1', false, 3, now(), now()),
    (v_q_id, 'Diverges for all L', false, 4, now(), now());

  INSERT INTO public.quiz_questions (
    quiz_id, type, prompt, explanation, difficulty, points, negative_marks,
    order_index, tags, year, exam_name, created_at, updated_at
  ) VALUES (
    v_quiz_id, 'single', 'Test the convergence of the series Σ n / 2^n using D''Alembert''s ratio test:', 'u_(n+1)/u_n = [(n+1)/2^(n+1)] * [2^n / n] = [(n+1)/(2n)] -> 1/2. Since L = 1/2 < 1, the series converges.',
    'medium', 1, 0, 19, ARRAY['BCA-401E', 'Unit-4', 'Ratio-Test', 'Application']::TEXT[], 2024, 'MJPRU BCA Sem 2',
    now(), now()
  ) RETURNING id INTO v_q_id;

  INSERT INTO public.quiz_options (question_id, text, is_correct, order_index, created_at, updated_at) VALUES
    (v_q_id, 'Convergent (L = 1/2 < 1)', true, 1, now(), now()),
    (v_q_id, 'Divergent (L = 2 > 1)', false, 2, now(), now()),
    (v_q_id, 'Test fails (L = 1)', false, 3, now(), now()),
    (v_q_id, 'Oscillatory', false, 4, now(), now());

  INSERT INTO public.quiz_questions (
    quiz_id, type, prompt, explanation, difficulty, points, negative_marks,
    order_index, tags, year, exam_name, created_at, updated_at
  ) VALUES (
    v_quiz_id, 'single', 'Test the convergence of the series Σ x^n / n! (for any real x > 0):', 'u_(n+1)/u_n = [x^(n+1) / (n+1)!] * [n! / x^n] = x / (n+1) -> 0 as n -> inf. L = 0 < 1 for all x, so it converges universally.',
    'medium', 1, 0, 20, ARRAY['BCA-401E', 'Unit-4', 'Ratio-Test', 'Exponential-Series']::TEXT[], 2024, 'MJPRU BCA Sem 2',
    now(), now()
  ) RETURNING id INTO v_q_id;

  INSERT INTO public.quiz_options (question_id, text, is_correct, order_index, created_at, updated_at) VALUES
    (v_q_id, 'Converges for all x > 0 (since L = lim x / (n+1) = 0 < 1)', true, 1, now(), now()),
    (v_q_id, 'Diverges for x > 1', false, 2, now(), now()),
    (v_q_id, 'Converges only if x < 1', false, 3, now(), now()),
    (v_q_id, 'Diverges for all x', false, 4, now(), now());

  INSERT INTO public.quiz_questions (
    quiz_id, type, prompt, explanation, difficulty, points, negative_marks,
    order_index, tags, year, exam_name, created_at, updated_at
  ) VALUES (
    v_quiz_id, 'single', 'Why does D''Alembert''s Ratio Test fail for all p-series Σ 1 / n^p?', 'For rational/algebraic terms, the ratio test limit is identically 1, requiring higher-order tests like Raabe''s test.',
    'medium', 1, 0, 21, ARRAY['BCA-401E', 'Unit-4', 'Ratio-Test', 'Limitation']::TEXT[], 2024, 'MJPRU BCA Sem 2',
    now(), now()
  ) RETURNING id INTO v_q_id;

  INSERT INTO public.quiz_options (question_id, text, is_correct, order_index, created_at, updated_at) VALUES
    (v_q_id, 'Because lim (u_(n+1) / u_n) = lim [n / (n+1)]^p = 1^p = 1 for all values of p', true, 1, now(), now()),
    (v_q_id, 'Because p-series terms are negative', false, 2, now(), now()),
    (v_q_id, 'Because p cannot be fractional', false, 3, now(), now()),
    (v_q_id, 'Because n! is absent', false, 4, now(), now());

  INSERT INTO public.quiz_questions (
    quiz_id, type, prompt, explanation, difficulty, points, negative_marks,
    order_index, tags, year, exam_name, created_at, updated_at
  ) VALUES (
    v_quiz_id, 'single', 'What is Cauchy''s Root Test (nth Root Test) for a positive term series Σ u_n with lim_{n->infinity} (u_n)^(1/n) = L?', 'Cauchy''s root test: L = lim (u_n)^(1/n). L < 1 => convergence; L > 1 => divergence; L = 1 => test fails.',
    'easy', 1, 0, 22, ARRAY['BCA-401E', 'Unit-4', 'Cauchy-Root-Test', 'Statement']::TEXT[], 2024, 'MJPRU BCA Sem 2',
    now(), now()
  ) RETURNING id INTO v_q_id;

  INSERT INTO public.quiz_options (question_id, text, is_correct, order_index, created_at, updated_at) VALUES
    (v_q_id, 'Converges if L < 1, diverges if L > 1, and test fails if L = 1', true, 1, now(), now()),
    (v_q_id, 'Converges if L > 1, diverges if L < 1', false, 2, now(), now()),
    (v_q_id, 'Converges if L = 1', false, 3, now(), now()),
    (v_q_id, 'Never fails', false, 4, now(), now());

