  ) VALUES (
    v_quiz_id, 'single', 'Can the terms of a conditionally convergent series be rearranged to equal ANY real number (Riemann''s Rearrangement Theorem)?', 'Riemann Rearrangement Theorem: by conditionally reordering positive and negative terms, any sum can be obtained.',
    'hard', 1, 0, 37, ARRAY['BCA-401E', 'Unit-4', 'Riemann-Rearrangement', 'Theorem']::TEXT[], 2024, 'MJPRU BCA Sem 2',
    now(), now()
  ) RETURNING id INTO v_q_id;

  INSERT INTO public.quiz_options (question_id, text, is_correct, order_index, created_at, updated_at) VALUES
