  ) VALUES (
    v_quiz_id, 'single', 'How is the Radius of Convergence R calculated using Cauchy-Hadamard formula?', 'The Cauchy-Hadamard formula states 1/R = limsup |a_n|^(1/n).',
    'medium', 1, 0, 41, ARRAY['BCA-401E', 'Unit-4', 'Cauchy-Hadamard', 'Formula']::TEXT[], 2024, 'MJPRU BCA Sem 2',
