  ) VALUES (
    v_quiz_id, 'single', 'How is the Radius of Convergence R calculated using the ratio of coefficients?', 'By the ratio test: |x| lim |a_(n+1)/a_n| < 1 => |x| < lim |a_n / a_(n+1)| = R.',
    'medium', 1, 0, 42, ARRAY['BCA-401E', 'Unit-4', 'Radius-of-Convergence', 'Ratio-Formula']::TEXT[], 2024, 'MJPRU BCA Sem 2',
    now(), now()
  ) RETURNING id INTO v_q_id;

