  ) VALUES (
    v_quiz_id, 'single', 'What are the three conditions required for Rolle''s Theorem to hold on an interval [a, b]?', 'Rolle''s theorem requires: (1) continuous on closed [a, b], (2) differentiable on open (a, b), (3) f(a) = f(b).',
    'easy', 1, 0, 1, ARRAY['BCA-401E', 'Unit-5', 'Rolles-Theorem', 'Conditions']::TEXT[], 2024, 'MJPRU BCA Sem 2',
    now(), now()
  ) RETURNING id INTO v_q_id;

