  INSERT INTO public.quiz_questions (
    quiz_id, type, prompt, explanation, difficulty, points, negative_marks,
    order_index, tags, year, exam_name, created_at, updated_at
  ) VALUES (
    v_quiz_id, 'single', 'Find the value of c guaranteed by LMVT for f(x) = x^2 on [1, 2]:', 'f''(c) = 2c. [f(2) - f(1)] / (2 - 1) = (4 - 1) / 1 = 3. 2c = 3 => c = 1.5 ∈ (1, 2).',
    'easy', 1, 0, 9, ARRAY['BCA-401E', 'Unit-5', 'LMVT', 'Calculation']::TEXT[], 2024, 'MJPRU BCA Sem 2',
    now(), now()
  ) RETURNING id INTO v_q_id;

