  ) VALUES (
    v_quiz_id, 'single', 'What is the alternative form of LMVT using step length h: f(a + h) = ?', 'Setting b = a + h and c = a + θh (with 0 < θ < 1) yields the fractional increment form of LMVT.',
    'medium', 1, 0, 10, ARRAY['BCA-401E', 'Unit-5', 'LMVT', 'Alternative-Form']::TEXT[], 2024, 'MJPRU BCA Sem 2',
    now(), now()
  ) RETURNING id INTO v_q_id;

