  INSERT INTO public.quiz_questions (
    quiz_id, type, prompt, explanation, difficulty, points, negative_marks,
    order_index, tags, year, exam_name, created_at, updated_at
  ) VALUES (
    v_quiz_id, 'single', 'How is Rolle''s Theorem related to Lagrange''s Mean Value Theorem?', 'If f(a) = f(b), then [f(b) - f(a)] / (b - a) = 0, directly reducing LMVT to Rolle''s f''(c) = 0.',
    'easy', 1, 0, 11, ARRAY['BCA-401E', 'Unit-5', 'Rolles-vs-LMVT', 'Relationship']::TEXT[], 2024, 'MJPRU BCA Sem 2',
    now(), now()
  ) RETURNING id INTO v_q_id;

  INSERT INTO public.quiz_options (question_id, text, is_correct, order_index, created_at, updated_at) VALUES
    (v_q_id, 'Rolle''s Theorem is a special case of LMVT where f(a) = f(b)', true, 1, now(), now()),
    (v_q_id, 'LMVT is a special case of Rolle''s', false, 2, now(), now()),
    (v_q_id, 'They are completely unrelated', false, 3, now(), now()),
    (v_q_id, 'Rolle''s applies to integration', false, 4, now(), now());

  INSERT INTO public.quiz_questions (
    quiz_id, type, prompt, explanation, difficulty, points, negative_marks,
