  ) VALUES (
    v_quiz_id, 'single', 'What are the conditions for Cauchy''s Mean Value Theorem for two functions f(x) and g(x) on [a, b]?', 'Cauchy''s MVT generalizes LMVT to two functions simultaneously, requiring g''(x) != 0 to avoid division by zero.',
    'medium', 1, 0, 12, ARRAY['BCA-401E', 'Unit-5', 'CMVT', 'Conditions']::TEXT[], 2024, 'MJPRU BCA Sem 2',
    now(), now()
  ) RETURNING id INTO v_q_id;

  INSERT INTO public.quiz_options (question_id, text, is_correct, order_index, created_at, updated_at) VALUES
