  INSERT INTO public.quiz_questions (
    quiz_id, type, prompt, explanation, difficulty, points, negative_marks,
    order_index, tags, year, exam_name, created_at, updated_at
  ) VALUES (
    v_quiz_id, 'single', 'What is the mathematical conclusion of Cauchy''s Mean Value Theorem?', 'The ratio of increments equals the ratio of instantaneous derivatives at some intermediate point c.',
    'medium', 1, 0, 13, ARRAY['BCA-401E', 'Unit-5', 'CMVT', 'Formula']::TEXT[], 2024, 'MJPRU BCA Sem 2',
    now(), now()
  ) RETURNING id INTO v_q_id;

  INSERT INTO public.quiz_options (question_id, text, is_correct, order_index, created_at, updated_at) VALUES
    (v_q_id, 'There exists c ∈ (a, b) such that [f(b) - f(a)] / [g(b) - g(a)] = f''(c) / g''(c)', true, 1, now(), now()),
