  INSERT INTO public.quiz_questions (
    quiz_id, type, prompt, explanation, difficulty, points, negative_marks,
    order_index, tags, year, exam_name, created_at, updated_at
  ) VALUES (
    v_quiz_id, 'single', 'If g(x) = x in Cauchy''s Mean Value Theorem, what does it reduce to?', 'When g(x) = x, g''(x) = 1 and g(b) - g(a) = b - a, yielding [f(b) - f(a)] / (b - a) = f''(c), which is LMVT.',
    'easy', 1, 0, 14, ARRAY['BCA-401E', 'Unit-5', 'CMVT', 'Reduction-to-LMVT']::TEXT[], 2024, 'MJPRU BCA Sem 2',
    now(), now()
  ) RETURNING id INTO v_q_id;

